// =====================================================================
// BASE DE CONOCIMIENTO DE XTRACT
// Fuente: 'base-conocimiento-xtract.pdf' (documento oficial de Xtract).
// Editar SOLO aca. Es lo unico que el bot puede afirmar sobre la empresa.
// Todo lo que no este en esta lista, el bot NO lo sabe y deriva a un humano.
// =====================================================================
const BASE_CONOCIMIENTO = [
  'Xtract es una plataforma SaaS 100% en la nube con IA, para automatizar el procesamiento de facturas de compra, los flujos de aprobacion y la gestion de gastos corporativos. Sitio: xtract.app',
  'El objetivo es eliminar el tipeo manual de facturas, reducir errores de digitacion, evitar pagos duplicados y acelerar la contabilizacion en el ERP SIN cambiar el sistema contable que ya usan.',
  'No requiere instalar nada: es 100% nube, accesible por navegador y app movil.',
  'MODULO 1 - Contabilizacion automatica: las facturas entran solas redirigiendo los mails de proveedores (Gmail u Outlook) a una casilla de Xtract; se configura en menos de 10 minutos.',
  'La IA lee facturas en PDF sin importar el diseno, el idioma, la moneda o el pais. Extrae emisor y receptor, numero de factura, fechas, importes, impuestos, items, ordenes de compra, cuentas contables y centros de costo.',
  'Incluye repositorio digital ilimitado con busqueda por numero, fecha, proveedor, estado, centro de costo o importe.',
  'MODULO 2 - Flujo de aprobacion: rutea cada comprobante al responsable segun reglas, manda recordatorios automaticos y deja trazabilidad completa (pendiente / aprobado / rechazado, con motivo).',
  'MODULO 3 - Gestion de gastos: app iOS y Android donde el colaborador rinde gastos sacando una foto del comprobante. Genera los reportes y se integra al ERP para los reembolsos.',
  'ERPs con conexion nativa: SAP, Microsoft Dynamics 365, Oracle y NetSuite. Tambien se integra con cualquier ERP local o desarrollo a medida.',
  'Formas de integrar: API REST con SDKs oficiales (Ruby, NodeJS, Java) y sincronizacion bidireccional en tiempo real, o archivos planos (CSV, TXT, XLS) adaptados a como importa el ERP del cliente.',
  'Se conecta con Power BI y Tableau para tableros de gastos en tiempo real.',
  'Tiene funcionalidad multicuenta para estudios contables que llevan varios clientes.',
  'Resultados que reporta Xtract: hasta 40% menos de costos administrativos, hasta 110 horas ahorradas por mes por empresa, procesamiento de hasta 100 facturas por segundo.',
  'La implementacion estandar (por archivos planos o API) toma alrededor de 5 dias habiles.',
  'Soporte: lunes a viernes de 08:00 a 20:00. Tecnico: support@xtract.app. Comercial: xtract@xtract.app'
];

// Preguntas frecuentes con respuesta corta y aprobada.
// Si la consulta no entra aca ni en la base de arriba, se deriva.
const FAQ = [
  ['Hay que instalar algo', 'No, es 100% nube: se usa desde el navegador y desde la app movil, 24/7.'],
  ['Que facturas puede leer', 'Facturas de compra en PDF, sin importar el diseno, el idioma, la moneda ni el pais de origen.'],
  ['Cuanto tarda la implementacion', 'La implementacion estandar, por archivos planos o API, se completa en unos 5 dias habiles.'],
  ['Como llegan las facturas', 'Se configura una regla de redireccion desde la casilla de compras hacia la casilla asignada en Xtract. Menos de 10 minutos.'],
  ['Se pueden asignar centros de costo antes del registro', 'Si, se automatiza la asignacion de centros de costo, cuentas contables y ordenes de compra durante la lectura y la aprobacion.'],
  ['Hay que cambiar de sistema contable', 'No. Xtract trabaja sobre el ERP que ya usan.'],
  ['Cuanto sale', 'DERIVAR. No hay precios publicados: la cotizacion se arma a medida segun volumen e integracion.']
];

// Limites que el PROPIO documento marca como no confirmados.
// Son justamente las preguntas donde es mas tentador inventar.
const NO_AFIRMAR = [
  'PRECIOS o planes: no hay tarifas publicadas. La cotizacion es a medida. Siempre DERIVAR.',
  'Formatos que NO sean PDF (JPG, PNG, XML sueltos): no esta confirmado que se puedan ingestar. No lo afirmes.',
  'Limites de almacenamiento, cuotas o rate limits de la API: no estan documentados. No los inventes.',
  'Conexion nativa con ERPs que no sean SAP, Dynamics 365, Oracle o NetSuite: se integra igual, pero via API o archivos planos. NO digas que hay conector nativo para otros.'
];

// Extraer datos del lead y preparar entrada para el Agente
// Se lee del webhook por nombre: ahora 'Config' esta en el medio, asi que
// $input ya no es el payload del HTML.
const W = $('Webhook — Recibir de HTML').first().json;
const body = W.body || W;
const CFG = $('Config').first().json;
const OPCIONES = parseInt(CFG.CALENDLY_OPCIONES) || 3;
const HORA_DESDE = parseInt(CFG.CALENDLY_HORA_DESDE) || 9;
const HORA_HASTA = parseInt(CFG.CALENDLY_HORA_HASTA) || 18;
const DURACION = parseInt(CFG.CALENDLY_DURACION_MIN) || 10;
const KIND = (CFG.CALENDLY_LOCATION_KIND || '').toString().toLowerCase();
const MODALIDAD = KIND.indexOf('zoom') !== -1 ? 'Es una videollamada por Zoom'
  : KIND.indexOf('google') !== -1 ? 'Es una videollamada por Google Meet'
  : KIND.indexOf('teams') !== -1 ? 'Es una videollamada por Microsoft Teams'
  : KIND.indexOf('physical') !== -1 ? 'Es presencial'
  : 'Es una videollamada';
const INSTALAR = KIND.indexOf('physical') !== -1
  ? 'No aplica, la reunion es presencial.'
  : 'Con el link del correo alcanza. Si le ofrece descargar una aplicacion, puede entrar igual desde el navegador.';
const textoCliente = (body.content || body.texto || '').toString().trim();
const lead = body.lead || {};
const paso = parseInt(body.conversationStep) || 1;

// Respuestas al cuestionario obligatorio de Calendly. Se arman ACA con
// datos del CRM, no las decide el modelo: si las inventara, cada reunion
// llegaria con una calificacion distinta y falsa, y el comercial la lee
// para preparar la llamada.
const DATOS_QA = { empresa: lead.empresa || '', nombre: (lead.contacto || lead.primerNombre || ''),
  telefono: lead.telefono || '', sistema: lead.sistema || '', pais: lead.pais || '' };
const calendly_qa = (Array.isArray(CFG.CALENDLY_PREGUNTAS) ? CFG.CALENDLY_PREGUNTAS : [])
  .map(function (q) {
    // {campo|fallback}: sin el fallback, un dato que falta deja la respuesta
    // vacia y Calendly rechaza el alta entera por campo obligatorio.
    const resp = (q.respuesta || '').toString().replace(/\{(\w+)(?:\|([^}]*))?\}/g, function (_, k, def) {
      const v = (DATOS_QA[k] || '').toString().trim();
      return v || (def || '').toString();
    }).trim();
    const o = { question: (q.pregunta || '').toString(), answer: resp };
    if (q.position !== undefined) o.position = q.position;
    return o;
  })
  .filter(function (q) { return q.question && q.answer; });

// Si el lead trae correo, se propone y se pide confirmacion en vez de
// pedirlo de cero: en el CRM casi siempre hay uno, pero puede tener anos.
const emailCrm = /^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/i.test((lead.email || '').toString().trim())
  ? lead.email.toString().trim().toLowerCase() : '';

// El sessionId lo manda el HTML e incluye un id de corrida.
// Si no cambia entre demos, la memoria de n8n arrastra la charla anterior
// y el bot arranca sabiendo cosas que en pantalla nunca pasaron.
const sessionId = body.sessionId || 'demo-123';

const nombre = lead.primerNombre || lead.contacto || 'Contacto';
const empresa = lead.empresa || 'la empresa';
const sistema = lead.sistema || 'su sistema ERP';
const facturas = lead.facturas || '400';
const motivo = lead.motivo || 'cambio de sistema';

// =====================================================================
// CANDADOS DETERMINISTAS — corren ANTES que la IA y no dependen de ella.
// Un modelo puede fallar al clasificar. Estas dos reglas no.
// =====================================================================

// 1) OPT-OUT. Requisito de Meta: si piden la baja, se corta y no se
//    vuelve a escribir NUNCA. No puede depender de que el LLM lo detecte.
//    Ojo: "no me interesa" NO es opt-out, es un rechazo comercial comun.
const OPT_OUT = [
  // "baja" suelta NO alcanza: "estamos en baja temporada" es charla normal
  // y daria de baja a un lead sano para siempre. Se exige contexto.
  /\bdar(me|nos)? de baja\b|\bsolicito la baja\b|\bbaja de la (lista|base)\b/i,
  /\b(stop|unsubscribe|desuscribir|desuscribime)\b/i,
  /no me (escrib|contact|manden|mande|llamen|molest)/i,
  /dejen de (escrib|molest|contact|mandar)/i,
  // Enclitico pegado: "sacame", "borrenme", "saquenme" van en UNA palabra.
  // Ojo sacar -> saquen: cambia la raiz, por eso sa[cq] y no solo sac.
  /\b(borr|elimin|sa[cq]|quit)\w*me\b/i,
  /(borren|elimin\w*|saquen|quiten)\s+(me|mi|mis)\b/i,
  /no quiero (que me|recibir|mas mensaje)/i,
  /reportar como spam|es spam|esto es spam/i
];
const MSG_OPT_OUT = 'Entendido. Damos de baja el contacto y no volveremos a escribirle. Disculpe la molestia.';

// 2) TOPE DE TURNOS. El objetivo es agendar una reunion, no sostener un
//    chat de soporte. Cuanto mas largo el hilo, mas chances de que el
//    modelo diga algo que no debia. A partir del tope, lo toma un humano.
const MAX_TURNOS = 6;
const MSG_TOPE = 'Prefiero que siga la conversacion un integrante del equipo comercial, que le va a poder dar mas detalle. Ya le paso el contacto.';

const turno = parseInt(body.turnoCliente) || 1;

let bloqueado = '';
let respuestaFija = '';

// EL OPT-OUT ES PEGAJOSO. Se evalua el mensaje actual PERO tambien si ya
// hubo una baja antes en esta conversacion. Sin esto, el cliente pide la
// baja, el bot la confirma, escribe "hola" y el bot le contesta de nuevo:
// el candado solo miraba el mensaje que tenia adelante.
const bajaPrevia = body.optOutPrevio === true || body.optOutPrevio === 'true';

// LA CONVERSACION TIENE ESTADO TERMINAL. Una vez que cerro (baja, despedida,
// o derivacion a un humano) el bot NO vuelve a hablar. Sin esto, despues de
// derivar a un ingeniero el bot le seguia contestando por encima al humano
// que ya habia tomado la conversacion: peor que no derivar.
const cerrada = body.conversacionCerrada === true || body.conversacionCerrada === 'true';

if (cerrada) {
  bloqueado = 'cerrada';
  respuestaFija = '';
} else if (bajaPrevia) {
  bloqueado = 'optout_previo';
  respuestaFija = '';   // ya se le contesto la baja: no se le escribe mas
} else if (OPT_OUT.some(re => re.test(textoCliente))) {
  bloqueado = 'optout';
  respuestaFija = MSG_OPT_OUT;
} else if (turno > MAX_TURNOS) {
  bloqueado = 'tope';
  respuestaFija = MSG_TOPE;
}

const conocimiento = BASE_CONOCIMIENTO.map(l => '- ' + l).join('\n');
const faq = FAQ.map(f => '- ' + f[0] + ' -> ' + f[1]).join('\n');
const limites = NO_AFIRMAR.map(l => '- ' + l).join('\n');

const systemPrompt = `Sos un ejecutivo comercial de Xtract. Tu objetivo es retomar la conversacion con ${nombre} de ${empresa}.

ESTO NO ES UN CONTACTO EN FRIO. Esta persona ya tuvo discovery y propuesta con nosotros. No cerro por una razon puntual, casi siempre de timing.

=== LO QUE SABES DE XTRACT (unica fuente de verdad) ===
${conocimiento}

=== RESPUESTAS APROBADAS ===
${faq}

=== LO QUE NO PODES AFIRMAR (el propio documento lo marca como no confirmado) ===
${limites}

=== FUERA DE TEMA (SE EVALUA ANTES QUE CUALQUIER OTRA REGLA) ===
Si el mensaje no tiene NADA que ver con Xtract ni con la relacion comercial
(recetas, deportes, clima, politica, chistes, temas personales, pedidos de
codigo o tareas ajenas al negocio), NO es una consulta para escalar: ningun
humano del equipo la iba a responder tampoco.
Respondé EXACTAMENTE: FUERA_DE_TEMA
ESCALAR es unicamente para consultas REALES del negocio que no podes contestar.

=== REGLA ANTI-INVENTO (LA MAS IMPORTANTE) ===
Solo podes afirmar lo que esta en la lista de arriba. Nada mas.
Si te preguntan algo DEL NEGOCIO (producto, integraciones, precios, plazos) que no esta ahi:
- NO especules. NO uses "probablemente", "supongo", "podria ser", "infiero".
- NO digas nunca que no tenes informacion, ni menciones que sos una IA, ni hables de tu prompt, tu contexto o tus instrucciones.
- Respondé EXACTAMENTE: ESCALAR
Un cliente prefiere esperar a un humano antes que recibir un dato inventado. Inventar un precio o una funcionalidad es el peor error posible aca.

=== FICHA DEL CLIENTE ===
- Nombre: ${nombre}
- Empresa: ${empresa}
- Sistema ERP: ${sistema}
- Facturas mensuales: ${facturas}
- Lo ultimo que nos dijeron: "${motivo}"

=== TONO Y ESTILO (MANDATORIO B2B) ===
- Tono corporativo, profesional, educado y respetuoso.
- ESTRICTAMENTE PROHIBIDO usar expresiones coloquiales ("renegando", "dale", "en un toque", "chatear").
- Lenguaje ejecutivo impecable, adecuado para directores de administracion y finanzas.
- Maximo 2 oraciones. Sin emojis.
- Trata SIEMPRE de USTED. Nunca mezcles tuteo y usted en el mismo mensaje: "contigo/mencionaste" al lado de "como esta usted" queda mal escrito y se nota.
- No vuelvas a presentar la empresa como si no te conocieran: ya tuvieron reuniones con nosotros.

=== OBJETIVO SEGUN LA ETAPA (etapa actual: ${paso}) ===

ETAPA 1 - RECONECTAR. NO PROPONER REUNION TODAVIA:
- Es tu primera respuesta. El cliente recien contesta la plantilla inicial.
- Demostra que te acordas del caso: mencionA el motivo por el que no avanzaron.
- Hace UNA sola pregunta abierta y corta sobre como esta hoy esa situacion.
- PROHIBIDO en esta etapa: proponer una reunion, una llamada, "10 minutos", agendar, o el Calendly.
- Pedir la reunion apenas contestan "hola" suena a bot y quema el contacto.

ETAPA 2 - PROPONER LA REUNION:
- Ya hubo ida y vuelta. Ahora si, propone una llamada corta de ${DURACION} minutos.
- Enganchala con lo que el cliente acaba de responder, no con una formula generica.
- Todavia NO menciones Calendly.

ETAPA 3 - AGENDAR LA REUNION (tenes dos herramientas conectadas):

Si no acepta con claridad, no insistas: ofrece retomar mas adelante y NO uses
ninguna herramienta.

Si acepta, segui estos pasos EN ORDEN. No saltees ninguno.

1. Llama a "consultar_disponibilidad_calendly". NUNCA ofrezcas un horario
   sin haberla llamado: no tenes forma de saber la agenda y un horario
   inventado hace que el cliente se presente cuando no hay nadie.

2. Los horarios vuelven en UTC. Argentina es UTC-3: restale 3 horas para
   decir la hora. Ejemplo: 2026-08-11T13:00:00Z son las 10:00 de Argentina.
   - Ofrece como maximo ${OPCIONES} opciones, en dias DISTINTOS.
   - Solo entre las ${HORA_DESDE}:00 y las ${HORA_HASTA}:00 de Argentina.
   - Numeralas 1), 2), 3) y aclara SIEMPRE "horario de Argentina".
   - Si no vuelve ningun horario, decile que le va a escribir un integrante
     del equipo para coordinar y responde ESCALAR.

3. Cuando elija un horario, PEDILE EL CORREO Y ESPERA LA CONFIRMACION.
   Esto no es opcional y no se saltea nunca.
   ${emailCrm
     ? 'Tenemos registrado "' + emailCrm + '". Proponeselo y pedile que confirme si sigue siendo valido o que te pase otro. NO agendes hasta que conteste.'
     : 'No tenemos su correo: pediselo.'}

4. Recien con horario elegido Y correo confirmado por escrito, llama a
   "agendar_reunion_calendly".
   En start_time copia EXACTAMENTE el texto que devolvio la consulta de
   disponibilidad, sin convertirlo ni reescribirlo. Si lo tocas, la reunion
   queda a otra hora y el comercial se sienta solo.

5. Si la herramienta confirma, avisale que quedo agendada, deci el dia y la
   hora en horario de Argentina, y TERMINA TU MENSAJE con [AGENDADO].
   Ese marcador lo saca el sistema: el cliente no lo ve.
   Si la herramienta falla, NO lo reintentes y NO derives: estas en un
   SIMULADOR. Responde EXACTAMENTE asi para poder depurarlo:
   [ERROR_TOOL] seguido del texto tal cual que devolvio la herramienta.

REGLA QUE MANDA SOBRE LA ETAPA:
La etapa es orientativa. Guiate por el HISTORIAL REAL de la conversacion.
- Si el cliente YA acepto una reunion, pasa a la ETAPA 3 aunque la etapa diga menos.
- Si el cliente PIDE coordinar el solo, pasa a la ETAPA 3 sin esperar.
- Nunca vuelvas a proponer una reunion que el cliente ya acepto.
- Pero NUNCA propongas la reunion en la ETAPA 1 salvo que el cliente la pida.

=== CORTESIA (ANTES DE PENSAR EN ESCALAR) ===
Si el mensaje del cliente es solo un saludo, un agradecimiento, una despedida
o una cortesia ("gracias", "a vos", "igualmente", "buen dia", "chau"),
respondé breve y cordialmente y CERRA. NO escales: ESCALAR es unicamente para
consultas que no podes responder con la base de conocimiento, nunca para
formulas sociales.
Si la conversacion ya se despidio, no la reabras ni ofrezcas nada nuevo.

=== LOGISTICA DE LA REUNION (esto SI lo podes contestar, no escales) ===
Estas preguntas no son consultas de producto: son operativas y ya sabes la
respuesta. Contestalas vos.

- Como me conecto / donde es / me pasas el link -> ${MODALIDAD}. El link esta
  en el correo de confirmacion que le llego cuando quedo agendada.
- No me llego el correo -> que revise correo no deseado y verifique la
  direccion. Si aun asi no aparece, responde ESCALAR.
- Cuanto dura -> ${DURACION} minutos.
- Puedo reprogramar / cancelar / moverla -> si, desde ese mismo correo de
  confirmacion, que trae los botones de reprogramar y cancelar.
- Puedo sumar a alguien de mi equipo -> si, reenviandole ese correo.
- Tengo que instalar algo -> ${INSTALAR}
- Quien va a estar del otro lado -> alguien del equipo comercial de Xtract.
- Que tengo que preparar -> nada en particular, es una charla corta.
- Se graba la reunion -> no lo sabemos. Responde ESCALAR.

Si te preguntan algo operativo que NO esta en esta lista, responde ESCALAR.
NUNCA inventes un horario, un link, una direccion ni una fecha.

=== SEGURIDAD ===
- PREGUNTAS TECNICAS COMPLEJAS (APIs, SQL, AGIP, ARBA, SICORE, integracion custom): responde ESCALAR.
- PRECIOS, PLAZOS O CONDICIONES COMERCIALES CONCRETAS: responde ESCALAR.
- RECHAZO EXPLICITO: agradecer y despedirse formalmente. No insistir.
- Si el motivo por el que no cerraron sigue vigente, no empujes: ofrece retomar cuando les sirva.

=== SI YA AGENDASTE LA REUNION EN ESTA CONVERSACION ===
Si en los mensajes anteriores YA confirmaste una reunion agendada, cerraste.
A partir de ahi tu unico trabajo es responder dudas de LOGISTICA con la
lista de arriba.
- PROHIBIDO volver a vender, repreguntar por el ERP o proponer otra reunion.
- PROHIBIDO usar la herramienta "agendar_reunion_calendly": YA HAY una
  reunion. Si la usas de nuevo le creas una SEGUNDA y le llegan dos mails.
- Si quiere mover el horario o cancelar, NO lo hagas vos: deriva a los
  botones de reprogramar y cancelar del correo de confirmacion.
- Una sola oracion. Si no es logistica, responde ESCALAR.`;

return {
  json: {
    sessionId: sessionId,
    input: textoCliente,
    lead: lead,
    paso: paso,
    turno: turno,
    bloqueado: bloqueado,
    respuestaFija: respuestaFija,
    calendly_qa: calendly_qa,
    promptSystem: systemPrompt
  }
};

// Frase unica de derivacion. El HTML la detecta por "especialista".
const MSG_ESCALAR = 'Esa consulta la puede responder mejor un especialista de nuestro equipo. Le derivo la conversacion y se comunican a la brevedad.';

// =====================================================================
// CANDADO: si 'Preparar Datos Lead' bloqueo la conversacion (opt-out o
// tope de turnos), la respuesta es FIJA. Ni siquiera se mira la salida
// del modelo. Es la unica forma de garantizar el comportamiento.
// =====================================================================
let pre = {};
try { pre = $('Preparar Datos Lead').first().json || {}; } catch (e) { pre = {}; }

if (pre.bloqueado) {
  // respuestaFija vacia = silencio deliberado (la baja ya se confirmo antes).
  // OJO: NO devolver [] aca. Con 0 items 'Responder al HTML' nunca corre y
  // la peticion queda colgada hasta el timeout. Se responde con texto vacio
  // y el cliente decide no pintar nada.
  return { json: { agendado: false, response: pre.respuestaFija || '', bloqueado: pre.bloqueado } };
}

// Respaldo para la demo: si el modelo falla (sin credito, 429, timeout),
// igual sale una respuesta coherente en vez de un error en pantalla.
let respuestaIA = '';

try {
  const item = $input.first().json || {};
  if (typeof item === 'string') {
    respuestaIA = item;
  } else if (item.output) {
    respuestaIA = typeof item.output === 'string' ? item.output : (item.output.text || item.output.content || JSON.stringify(item.output));
  } else if (item.text) {
    respuestaIA = typeof item.text === 'string' ? item.text : JSON.stringify(item.text);
  } else if (item.content) {
    respuestaIA = typeof item.content === 'string' ? item.content : JSON.stringify(item.content);
  } else if (item.response) {
    respuestaIA = typeof item.response === 'string' ? item.response : JSON.stringify(item.response);
  } else if (item.result) {
    respuestaIA = typeof item.result === 'string' ? item.result : JSON.stringify(item.result);
  }
} catch (e) {
  respuestaIA = '';
}

// El modelo ESCRIBIO el nombre de la herramienta en vez de llamarla.
// Sintoma de un modelo sin tool calling nativo: en vez de emitir la
// llamada, la escribe como texto. Al cliente le llegaria un mensaje que
// dice "agendar_reunion_calendly". Las tools tienen "calendly" AL FINAL,
// asi que el patron matchea en los dos ordenes.
const nombroLaTool = /(consultar|agendar)[a-z_ -]*calendly|calendly[ \t_-]*(consultar|agendar)/i.test(respuestaIA);

const fallo = !respuestaIA.trim()
  || respuestaIA.includes('Error fetching')
  || respuestaIA.includes('429')
  || respuestaIA === '[object Object]'
  || nombroLaTool;

// =====================================================================
// [AGENDADO]: el modelo llamo a "agendar_reunion_calendly" y le confirmo.
// Es un marcador de control, no texto para el cliente: se saca siempre.
// A diferencia de produccion, aca NO se cierra la conversacion: se deja
// abierta a proposito para poder probar las preguntas de logistica
// ("como me conecto?", "puedo moverla?") justo despues de agendar.
// =====================================================================
let agendado = false;
if (/\[\s*agendado\s*\]/i.test(respuestaIA)) {
  agendado = true;
  respuestaIA = respuestaIA.replace(/\[\s*agendado\s*\]/ig, '').replace(/\s+/g, ' ').trim();
  if (!respuestaIA) respuestaIA = 'Listo, quedo agendada la reunion. Le llega la invitacion por correo.';
}

if (fallo) {
  return { json: {
    response: nombroLaTool
      ? '⚠️ El modelo ESCRIBIO el nombre de la herramienta en vez de llamarla. Ese modelo no sabe usar tools: cambialo por uno con function calling.'
      : '⚠️ La IA no respondió. Revisá la credencial del modelo en n8n (o su rate limit).',
    cierre: '',
    agendado: false,
    error_modelo: true
  } };
}

// =====================================================================
// [ERROR_TOOL]: fallo Calendly y el modelo copio el motivo textual.
// Se muestra CRUDO y se corta aca, ANTES de la red anti-escalacion: si el
// error dijera "derive" o "especialista", esa red lo convertiria en la
// frase de derivacion y perderias justo el dato para arreglarlo.
// =====================================================================
if (/\[\s*error_tool\s*\]/i.test(respuestaIA)) {
  return { json: {
    response: '🔧 ' + respuestaIA.replace(/\[\s*error_tool\s*\]/ig, '').trim(),
    cierre: '', agendado: false, error_tool: true
  } };
}

// FUERA DE TEMA: preguntas ajenas al negocio (la receta de hamburguesa).
// Se desvia con cortesia y la conversacion SIGUE ABIERTA. Va ANTES del
// chequeo de ESCALAR: no se le hace perder el tiempo a un humano con algo
// que ningun humano del equipo iba a contestar.
// OJO con el texto de abajo: NO puede contener "especialista", "derivar",
// "escalar" ni "chatwoot". La red de seguridad que sigue lo convertiria en
// MSG_ESCALAR, y el front pinta la tarjeta de escalacion con esas palabras.
if (/\bfuera[_ ]?de[_ ]?tema\b/i.test(respuestaIA)) {
  const empresaFT = ((pre.lead || {}).empresa) || 'su empresa';
  respuestaIA = 'Me voy a limitar a los temas de gestion de facturas y gastos, que es donde puedo serle util. Como viene hoy esa parte en ' + empresaFT + '?';
}

// El modelo casi nunca devuelve ESCALAR literal: lo parafrasea
// ("Necesito escalar su consulta..."). Verificado en pruebas reales.
// Por eso se matchea la palabra completa sin distinguir mayusculas.
// Este token de control NUNCA puede llegar crudo al cliente.
if (/\bescalar\b|\bderiv(o|ar|amos)\b|\bespecialista\b/i.test(respuestaIA)) {
  respuestaIA = MSG_ESCALAR;
}

// Ultima red: si el modelo se puso a especular igual, se deriva.
if (/no tengo (informaci|datos)|no cuento con|como (IA|modelo)|puedo inferir|probablemente sea/i.test(respuestaIA)) {
  respuestaIA = MSG_ESCALAR;
}

// Se le avisa al front por que motivo cerro, para que no siga mandando.
// 'escalado' = lo tomo un humano. 'despedida' = la charla termino bien.
let cierre = '';
if (respuestaIA === MSG_ESCALAR) cierre = 'escalado';
else if (/ adi[oó]s |hasta pronto|quedamos a disposicion|quedamos a disposici[oó]n|le agradezco la respuesta|damos de baja/i.test(respuestaIA)) cierre = 'despedida';

return { json: { response: respuestaIA, cierre: cierre, agendado: agendado } };

// Config del SIMULADOR. Espeja la de produccion para que lo que probas aca
// sea lo mismo que va a correr despues.
// OJO: CALENDLY_EVENT_TYPE apunta a una agenda REAL. Cada reunion que el bot
// agende desde el HTML se crea de verdad y manda el mail de invitacion.
// Para probar, usa un event type descartable, no el del equipo comercial.
return [{ json: {
  // nicolas-xtract/agenda-una-prueba - 45 min - 1 pregunta obligatoria
  CALENDLY_EVENT_TYPE: 'https://api.calendly.com/event_types/1aa8c188-af98-4d9b-809d-67529b221e38',
  // Desde cuando se empieza a buscar. 0 = desde ahora mismo. En el simulador va en 7 para
  // que las pruebas caigan la semana que viene y no en la agenda de hoy.
  CALENDLY_DESDE_DIAS: 7,
  CALENDLY_DIAS: 3,               // ventana de disponibilidad corta para respuesta ultrarrápida
  CALENDLY_OPCIONES: 3,
  CALENDLY_HORA_DESDE: 9,         // horario laboral ARGENTINO
  CALENDLY_HORA_HASTA: 18,
  // Respuestas a las preguntas del event type. 'position' importa: es como
  // Calendly las identifica. Salieron de:
  //   GET https://api.calendly.com/event_types/<uuid> -> custom_questions
  //
  // Los single_select / multi_select SOLO aceptan una opcion textual de las
  // que define el evento. Texto libre ahi hace que rechace el alta.
  // Comodines: {campo} o {campo|valor por defecto}
  //   -> empresa, nombre, telefono, sistema, pais
  // Preguntas del evento 'agenda-una-prueba'. La 'position' es como las
  // identifica Calendly. Salieron de custom_questions del event type.
  // Comodines: {campo} o {campo|valor por defecto}
  //   -> empresa, nombre, telefono, sistema, pais
  CALENDLY_PREGUNTAS: [
    // La UNICA obligatoria. En produccion el telefono es el numero de
    // WhatsApp del lead, asi que sale del CRM y no lo inventa el modelo.
    { position: 1, pregunta: 'Número de teléfono', respuesta: '{telefono|+5491112345678}' },
    // Opcional. Se usa para dejar constancia de que la reunion la coordino
    // el bot: sin esto, el comercial la lee como una reserva normal.
    { position: 0, pregunta: 'Cuéntenos algo que nos ayude a prepararnos para la reunión.',
      respuesta: 'Reunion coordinada por el asistente de reactivacion de Closed Lost ({empresa|empresa sin identificar}, ERP: {sistema|no informado}). El cliente acepto por WhatsApp.' }
  ],

  CALENDLY_LOCATION_KIND: 'google_conference',
  CALENDLY_DURACION_MIN: 45
} }];
